<template>
  <div>
    <div class="page-header">
      <div><h2>客户与负责人分配</h2><p>统一维护客户编号、订单员、分拣员和配送员，为企业微信自动识别客户提供基础资料</p></div>
      <div class="actions"><el-button type="primary" plain :disabled="!selected.length" @click="openBatch"><el-icon><UserFilled/></el-icon>批量分配人员（{{selected.length}}）</el-button><el-button type="danger" plain :disabled="!selected.length" @click="batchRemove">批量删除</el-button><el-button type="primary" @click="openCreate"><el-icon><Plus/></el-icon>新增客户</el-button></div>
    </div>

    <el-row :gutter="14" class="metrics"><el-col :span="6"><el-card class="panel metric"><span>客户总数</span><strong>{{rows.length}}</strong></el-card></el-col><el-col :span="6"><el-card class="panel metric"><span>未分配订单员</span><strong class="warning">{{rows.filter(r=>!r.order_clerk_id).length}}</strong></el-card></el-col><el-col :span="6"><el-card class="panel metric"><span>未分配分拣员</span><strong class="warning">{{rows.filter(r=>!r.sorter_id).length}}</strong></el-card></el-col><el-col :span="6"><el-card class="panel metric"><span>未分配配送员</span><strong class="warning">{{rows.filter(r=>!r.delivery_id).length}}</strong></el-card></el-col></el-row>

    <el-card class="panel responsibility">
      <div class="panel-title"><div><strong>负责人看板</strong><span>点击人员即可查看他负责的客户</span></div><el-button v-if="staffFilter" link type="primary" @click="staffFilter=''">清除人员筛选</el-button></div>
      <el-tabs v-model="staffTab">
        <el-tab-pane label="订单员负责情况" name="clerk"><div class="staff-grid"><div v-for="person in clerks" :key="person.id" class="staff-card" :class="{active:staffFilter===`o-${person.id}`}" @click="toggleStaff('o',person.id)"><el-avatar>{{person.name.slice(0,1)}}</el-avatar><div><strong>{{person.name}}</strong><small>{{person.role==='admin'?'管理员':'订单员'}}</small></div><span><b>{{customerCount('o',person.id)}}</b> 个客户</span></div><div class="staff-card unassigned" :class="{active:staffFilter==='o-0'}" @click="toggleStaff('o',0)"><el-avatar>未</el-avatar><div><strong>未分配订单员</strong><small>微信订单无法自动分派</small></div><span><b>{{rows.filter(r=>!r.order_clerk_id).length}}</b> 个客户</span></div></div></el-tab-pane>
        <el-tab-pane label="分拣员负责情况" name="sorter"><div class="staff-grid"><div v-for="person in sorters" :key="person.id" class="staff-card" :class="{active:staffFilter===`s-${person.id}`}" @click="toggleStaff('s',person.id)"><el-avatar>{{person.name.slice(0,1)}}</el-avatar><div><strong>{{person.name}}</strong><small>{{person.phone||'暂无电话'}}</small></div><span><b>{{customerCount('s',person.id)}}</b> 个客户</span></div><div class="staff-card unassigned" :class="{active:staffFilter==='s-0'}" @click="toggleStaff('s',0)"><el-avatar>未</el-avatar><div><strong>未分配分拣员</strong><small>需要尽快安排</small></div><span><b>{{rows.filter(r=>!r.sorter_id).length}}</b> 个客户</span></div></div></el-tab-pane>
        <el-tab-pane label="配送员负责情况" name="delivery"><div class="staff-grid"><div v-for="person in deliveries" :key="person.id" class="staff-card" :class="{active:staffFilter===`d-${person.id}`}" @click="toggleStaff('d',person.id)"><el-avatar>{{person.name.slice(0,1)}}</el-avatar><div><strong>{{person.name}}</strong><small>{{person.phone||'暂无电话'}}</small></div><span><b>{{customerCount('d',person.id)}}</b> 个客户</span></div><div class="staff-card unassigned" :class="{active:staffFilter==='d-0'}" @click="toggleStaff('d',0)"><el-avatar>未</el-avatar><div><strong>未分配配送员</strong><small>需要尽快安排</small></div><span><b>{{rows.filter(r=>!r.delivery_id).length}}</b> 个客户</span></div></div></el-tab-pane>
      </el-tabs>
    </el-card>

    <el-card class="panel customer-table">
      <div class="toolbar"><el-input v-model="keyword" clearable prefix-icon="Search" placeholder="搜索客户编号、客户、联系人或订单员" style="width:380px"/><el-tag v-if="staffFilter" closable @close="staffFilter=''">当前筛选：{{filterLabel}}</el-tag><span class="result-count">显示 {{filtered.length}} 个客户</span></div>
      <el-table :data="filtered" @selection-change="selected=$event"><el-table-column type="selection" width="46"/><el-table-column prop="customer_code" label="客户编号" min-width="125"/><el-table-column prop="name" label="客户名称" min-width="150"/><el-table-column prop="contact_name" label="联系人"/><el-table-column prop="phone" label="电话" min-width="130"/><el-table-column label="订单员" min-width="120"><template #default="s"><el-tag :type="s.row.order_clerk_id?'':'warning'" effect="plain">{{clerkName(s.row.order_clerk_id)||'未分配'}}</el-tag></template></el-table-column><el-table-column label="分拣员" min-width="120"><template #default="s"><el-tag :type="s.row.sorter_id?'primary':'warning'" effect="plain">{{staffName(s.row.sorter_id)||'未分配'}}</el-tag></template></el-table-column><el-table-column label="配送员" min-width="120"><template #default="s"><el-tag :type="s.row.delivery_id?'success':'warning'" effect="plain">{{staffName(s.row.delivery_id)||'未分配'}}</el-tag></template></el-table-column><el-table-column label="状态" width="80"><template #default="s">{{s.row.active?'启用':'停用'}}</template></el-table-column><el-table-column label="操作" width="140"><template #default="s"><el-button link type="primary" @click="openEdit(s.row)">编辑/分配</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table>
    </el-card>

    <el-dialog v-model="batchVisible" title="批量分配客户负责人" width="560px"><el-alert :title="`将为已选择的 ${selected.length} 个客户批量设置负责人；未选择的人员类型保持原分配不变。`" type="info" :closable="false"/><el-form label-width="105px" style="margin-top:20px"><el-form-item label="订单员"><el-select v-model="batchForm.order_clerk_id" clearable filterable placeholder="不修改订单员" style="width:100%"><el-option v-for="s in clerks" :key="s.id" :label="`${s.name}（当前 ${customerCount('o',s.id)} 个客户）`" :value="s.id"/></el-select></el-form-item><el-form-item label="分拣员"><el-select v-model="batchForm.sorter_id" clearable filterable placeholder="不修改分拣员" style="width:100%"><el-option v-for="s in sorters" :key="s.id" :label="`${s.name}（当前 ${customerCount('s',s.id)} 个客户）`" :value="s.id"/></el-select></el-form-item><el-form-item label="配送员"><el-select v-model="batchForm.delivery_id" clearable filterable placeholder="不修改配送员" style="width:100%"><el-option v-for="s in deliveries" :key="s.id" :label="`${s.name}（当前 ${customerCount('d',s.id)} 个客户）`" :value="s.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="batchVisible=false">取消</el-button><el-button type="primary" @click="saveBatch">确认批量分配</el-button></template></el-dialog>

    <el-dialog v-model="visible" :title="form.id?'编辑客户及人员分配':'新增客户'" width="680px"><el-form label-width="105px"><el-row :gutter="14"><el-col :span="12"><el-form-item label="客户编号"><el-input v-model="form.customer_code" placeholder="留空自动生成"/></el-form-item></el-col><el-col :span="12"><el-form-item label="客户名称" required><el-input v-model="form.name"/></el-form-item></el-col></el-row><el-row :gutter="14"><el-col :span="12"><el-form-item label="联系人"><el-input v-model="form.contact_name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="电话"><el-input v-model="form.phone"/></el-form-item></el-col></el-row><el-form-item label="客户地址"><el-input v-model="form.address"/></el-form-item><el-divider>人员分配</el-divider><el-form-item label="订单员"><el-select v-model="form.order_clerk_id" clearable filterable style="width:100%"><el-option v-for="s in clerks" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-row :gutter="14"><el-col :span="12"><el-form-item label="分拣员"><el-select v-model="form.sorter_id" clearable filterable style="width:100%"><el-option v-for="s in sorters" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="配送员"><el-select v-model="form.delivery_id" clearable filterable style="width:100%"><el-option v-for="s in deliveries" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-col></el-row><el-form-item label="AI回复规则"><el-input v-model="form.ai_reply_rules" type="textarea" :rows="3" placeholder="例如：客户把上海青称为青菜；每天下午4点前截单"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item><el-form-item v-if="form.id" label="状态"><el-switch v-model="form.active"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存客户</el-button></template></el-dialog>
  </div>
</template>

<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { batchAssignCustomers,createCustomer,deleteCustomer,getCustomerOrderClerks,getCustomers,getStaff,updateCustomer } from '@/api'
const rows=ref([]),staff=ref([]),clerks=ref([]),selected=ref([]),visible=ref(false),batchVisible=ref(false),keyword=ref(''),staffFilter=ref(''),staffTab=ref('clerk')
const blank=()=>({id:null,customer_code:'',name:'',contact_name:'',phone:'',address:'',order_clerk_id:null,sorter_id:null,delivery_id:null,ai_reply_rules:'',remark:'',active:true});const form=reactive(blank());const batchForm=reactive({order_clerk_id:null,sorter_id:null,delivery_id:null})
const sorters=computed(()=>staff.value.filter(s=>s.active&&s.staff_type==='sorter'));const deliveries=computed(()=>staff.value.filter(s=>s.active&&s.staff_type==='delivery'));const staffName=id=>staff.value.find(s=>s.id===id)?.name;const clerkName=id=>clerks.value.find(s=>s.id===id)?.name
const filtered=computed(()=>rows.value.filter(r=>{const term=keyword.value.toLowerCase();const text=`${r.customer_code||''}${r.name}${r.contact_name||''}${r.phone||''}${r.address||''}${clerkName(r.order_clerk_id)||''}`.toLowerCase();const [type,idText]=staffFilter.value.split('-');const id=Number(idText);const assigned=type==='s'?r.sorter_id:type==='d'?r.delivery_id:r.order_clerk_id;return(!term||text.includes(term))&&(!staffFilter.value||(id===0?!assigned:assigned===id))}))
const filterLabel=computed(()=>{if(!staffFilter.value)return'';const[type,idText]=staffFilter.value.split('-'),id=Number(idText),label=type==='s'?'分拣员':type==='d'?'配送员':'订单员',name=type==='o'?clerkName(id):staffName(id);return id===0?`未分配${label}`:`${label}：${name}`})
const customerCount=(type,id)=>rows.value.filter(r=>(type==='s'?r.sorter_id:type==='d'?r.delivery_id:r.order_clerk_id)===id).length;const toggleStaff=(type,id)=>{const value=`${type}-${id}`;staffFilter.value=staffFilter.value===value?'':value};const load=async()=>[rows.value,staff.value,clerks.value]=await Promise.all([getCustomers(),getStaff(),getCustomerOrderClerks()]);const openCreate=()=>{Object.assign(form,blank());visible.value=true};const openEdit=r=>{Object.assign(form,blank(),r);visible.value=true};const payload=()=>({customer_code:form.customer_code?.trim()||null,name:form.name.trim(),contact_name:form.contact_name||null,phone:form.phone||null,address:form.address||null,order_clerk_id:form.order_clerk_id,sorter_id:form.sorter_id,delivery_id:form.delivery_id,ai_reply_rules:form.ai_reply_rules||null,remark:form.remark||null,active:form.active})
const save=async()=>{if(!form.name.trim())return ElMessage.warning('请输入客户名称');if(form.id)await updateCustomer(form.id,payload());else await createCustomer(payload());ElMessage.success('客户及人员分配已保存');visible.value=false;load()};const openBatch=()=>{Object.assign(batchForm,{order_clerk_id:null,sorter_id:null,delivery_id:null});batchVisible.value=true};const saveBatch=async()=>{if(!batchForm.order_clerk_id&&!batchForm.sorter_id&&!batchForm.delivery_id)return ElMessage.warning('请至少选择一名订单员、分拣员或配送员');const result=await batchAssignCustomers({customer_ids:selected.value.map(r=>r.id),...batchForm});ElMessage.success(result.message);batchVisible.value=false;selected.value=[];load()};const remove=async r=>{await ElMessageBox.confirm(`确认删除客户“${r.name}”吗？`,'删除客户',{type:'warning'});const res=await deleteCustomer(r.id);ElMessage.success(res.message);load()};const batchRemove=async()=>{await ElMessageBox.confirm(`确认批量删除 ${selected.value.length} 个客户吗？`,'批量删除',{type:'warning'});for(const row of selected.value)await deleteCustomer(row.id);ElMessage.success('批量删除完成');load()};onMounted(load)
</script>

<style scoped>
.actions{display:flex;gap:10px}.metrics{margin-bottom:16px}.metric :deep(.el-card__body){display:flex;justify-content:space-between;align-items:center}.metric span{color:#8490a3}.metric strong{font-size:27px}.warning{color:#dd8730}.success{color:#24946b}.responsibility{margin-bottom:16px}.panel-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}.panel-title>div{display:flex;gap:12px;align-items:center}.panel-title span{color:#8b93a5;font-size:13px}.staff-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.staff-card{display:grid;grid-template-columns:42px 1fr auto;align-items:center;gap:10px;padding:12px;border:1px solid #e4e9f0;border-radius:10px;cursor:pointer;transition:.2s}.staff-card:hover,.staff-card.active{border-color:#4c89db;background:#f0f6ff}.staff-card small{display:block;color:#8b93a5;margin-top:4px}.staff-card>span{color:#78859a;font-size:13px}.staff-card b{font-size:20px;color:#347bd2}.staff-card.unassigned b{color:#dc8730}.customer-table .toolbar{justify-content:flex-start}.result-count{margin-left:auto;color:#8b93a5;font-size:13px}
</style>
